// site-gen-headers — render site/public/_headers from site/src/headers.ts.
//
// WHY THIS EXISTS
//
// The website answers requests from two places that cannot see each other.
// Cloudflare's static-asset layer serves the six content pages and never starts
// the Worker; the Worker generates the /go/* redirects and the 404. Cloudflare
// documents that the `_headers` file is not applied to responses generated by
// Worker code, so neither mechanism can cover the whole site: the pages need
// `_headers`, and the Worker has to attach the same table itself.
//
// A security header table written down twice drifts, and drifts silently —
// each copy is exercised by requests the other never sees, so a `Referrer-Policy`
// that fell out of one half keeps testing green in the other. So the table is
// written once, in site/src/headers.ts. site/worker/index.ts imports it. This
// script renders it into the file the asset layer reads. Nobody types a header
// name into `_headers` by hand, and there is nothing for a reviewer to diff
// against a specification, because the specification is the input.
//
//   node scripts/site-gen-headers.mjs
//
// Exit 0 after writing site/public/_headers, 1 with a named reason otherwise.
// scripts/site-copy-lint.mjs --dist re-checks after the build that the file
// reached site/dist and still contains every key, because "the generator was
// never run" is a failure this script cannot report about itself.
//
// ── WHY IT PARSES TYPESCRIPT INSTEAD OF IMPORTING IT ───────────────────────
//
// headers.ts is TypeScript, and Node cannot import that. The three ways out:
//
//   compile it        needs a TypeScript compiler in the build path for one
//                     40-line file. site/ has exactly one dependency (astro)
//                     and a clean `npm audit`; this is not worth a second.
//   regex the values  the CSP is assembled as `[...].join('; ')`, so a
//                     line-wise `'Name': 'value'` regex would silently emit a
//                     site with no Content-Security-Policy at all — the single
//                     most important header, missing, with a green build.
//   evaluate the object literal   what this file does. The initializer is
//                     plain JavaScript once the type annotation before `=` is
//                     stepped over, so the values this script writes are
//                     produced by the same expressions the Worker will run.
//
// The zero-install property from scripts/check-packaging-invariants.mjs holds:
// node builtins only.
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

const REPO_ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const HEADERS_TS = join(REPO_ROOT, 'site', 'src', 'headers.ts');
const OUTPUT = join(REPO_ROOT, 'site', 'public', '_headers');

/**
 * Cloudflare's `_headers` syntax: a path line, then the headers indented
 * beneath it. `/*` is every response the asset layer produces — the six pages
 * plus CSS and images. There is deliberately no `/go/*` block here: those
 * responses come from the Worker, where this file has no effect, and a block
 * for them would read as coverage that does not exist.
 */
const APPLY_TO = '/*';

/**
 * Fail with a message that says what to do, in the style of
 * check-packaging-invariants.mjs. Every exit from this script goes through
 * here so that no failure mode can degrade into "wrote an empty file".
 */
function fail(message) {
  console.error(`site-gen-headers: ${message}`);
  process.exit(1);
}

/**
 * The source text of the object literal assigned to `export const <name>`.
 *
 * Scans forward brace by brace rather than matching a regex against the whole
 * declaration, because the literal contains `//` comments and quoted strings,
 * and a non-greedy `\{.*?\}` would stop at whichever brace appeared first
 * inside one of them. Returns null when the declaration is absent; callers
 * decide whether that is fatal, since one of the two tables read here is
 * conditional.
 */
function objectLiteralOf(source, name) {
  const declaration = new RegExp(`export\\s+const\\s+${name}\\b[^=]*=\\s*`).exec(source);
  if (!declaration) return null;

  let index = declaration.index + declaration[0].length;
  if (source[index] !== '{') return null;

  const start = index;
  let depth = 0;
  while (index < source.length) {
    const char = source[index];

    // Skip over the things that contain braces without meaning them.
    if (char === '/' && source[index + 1] === '/') {
      index = source.indexOf('\n', index);
      if (index === -1) break;
      continue;
    }
    if (char === '/' && source[index + 1] === '*') {
      const end = source.indexOf('*/', index + 2);
      if (end === -1) break;
      index = end + 2;
      continue;
    }
    if (char === "'" || char === '"' || char === '`') {
      index += 1;
      while (index < source.length && source[index] !== char) {
        // A backslash escapes the next character, including the closing quote.
        index += source[index] === '\\' ? 2 : 1;
      }
      index += 1;
      continue;
    }

    if (char === '{') depth += 1;
    if (char === '}') {
      depth -= 1;
      if (depth === 0) return source.slice(start, index + 1);
    }
    index += 1;
  }
  return null;
}

/**
 * Evaluate one exported header table.
 *
 * `optional` exists for HSTS, which the table only sends once a real domain is
 * in play; every other absence is a headers.ts that this script no longer
 * understands, and that has to stop the build rather than produce a page with
 * fewer protections than the Worker sends for the same site.
 */
function readTable(source, name, { optional = false } = {}) {
  const literal = objectLiteralOf(source, name);
  if (!literal) {
    if (optional) return {};
    fail(`could not find the object literal for \`export const ${name}\` in site/src/headers.ts.
  This script reads that declaration directly. If the table was renamed or its
  shape changed, update the name here in the same commit — do not hand-write
  site/public/_headers, which is the situation this script exists to prevent.`);
  }

  let table;
  try {
    // The literal is plain JavaScript: string keys, string values, and one
    // `[...].join('; ')`. Evaluating it is what keeps the emitted CSP byte-
    // identical to the one worker/index.ts attaches.
    table = new Function(`return (${literal});`)();
  } catch (error) {
    fail(`\`${name}\` in site/src/headers.ts did not evaluate as a plain object: ${error.message}`);
  }

  if (!table || typeof table !== 'object' || Array.isArray(table)) {
    fail(`\`${name}\` in site/src/headers.ts is not an object.`);
  }
  for (const [key, value] of Object.entries(table)) {
    if (typeof value !== 'string' || value.length === 0) {
      fail(`header \`${key}\` in \`${name}\` is not a non-empty string.`);
    }
    if (/[\r\n]/.test(key + value)) {
      // A newline inside a value would end the header line and start a new
      // one, which is header injection performed on ourselves.
      fail(`header \`${key}\` in \`${name}\` contains a line break.`);
    }
  }
  return table;
}

const source = readFileSync(HEADERS_TS, 'utf8');

// HSTS is conditional in headers.ts's own staticHeaders(), and the condition is
// NOT "SITE_ORIGIN is set" — it is "SITE_ORIGIN names a host we may pin".
//
// This distinction is the entire bug this block used to have. `Boolean(origin)`
// looks equivalent right up to the first deploy, which is to *.workers.dev with
// SITE_ORIGIN set to that URL. There the Worker refuses HSTS, because pinning a
// hostname shared with every other Worker on the platform is not ours to do,
// and the static layer would have pinned it anyway. Six pages and five
// redirects disagreeing about a header the browser is asked to REMEMBER is the
// worst kind of disagreement: it outlives the deploy that caused it.
//
// The predicate is spelled out again here rather than imported because
// headers.ts is TypeScript and this file is dependency-free by design (see the
// note above). That duplication is the cost of the zero-install property, so it
// is written to be obvious: same two exclusions, same order, named after the
// function it mirrors. If hostAllowsHsts() ever grows a third exclusion, this
// is the other place to edit — and site/worker/index.test.ts covers the Worker
// half, so a divergence shows up as a test that still passes while curl shows
// two different answers. Keep them in one commit.
const mirrorsHostAllowsHsts = (hostname) =>
  hostname.length > 0 && !hostname.endsWith('.workers.dev') && hostname !== 'localhost';

const rawOrigin = process.env.SITE_ORIGIN?.trim();
let withHsts = false;
if (rawOrigin) {
  try {
    withHsts = mirrorsHostAllowsHsts(new URL(rawOrigin).hostname);
  } catch {
    // Not a URL. Treated as "no domain yet" rather than as a reason to pin
    // something unparseable.
    withHsts = false;
  }
}

const headers = {
  ...readTable(source, 'BASE_HEADERS'),
  ...(withHsts ? readTable(source, 'HSTS_HEADER', { optional: true }) : {}),
};

const names = Object.keys(headers);
// The empty-result guard. Every failure above is specific; this one catches the
// case none of them can — a headers.ts that parses, evaluates, and yields
// nothing. A generator that writes an empty file on success is indistinguishable
// from a site with no security headers, and it would be discovered by a scanner
// rather than by CI.
if (names.length === 0) {
  fail('extracted zero headers from site/src/headers.ts. Refusing to write an empty _headers.');
}

const rendered = [
  '# Generated by scripts/site-gen-headers.mjs from site/src/headers.ts.',
  '# Do not edit. Edit headers.ts; the Worker reads the same table for the',
  '# responses it generates, which this file does not cover.',
  APPLY_TO,
  ...names.map((name) => `  ${name}: ${headers[name]}`),
  '',
].join('\n');

mkdirSync(dirname(OUTPUT), { recursive: true });
writeFileSync(OUTPUT, rendered, 'utf8');

console.log(`site-gen-headers: wrote site/public/_headers (${names.length} headers)`);
console.log(rendered);
